#include <errno.h>
#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "usage: %s N\n", argv[0]);
        return EXIT_FAILURE;
    }

    char *end = NULL;
    errno = 0;
    long long n = strtoll(argv[1], &end, 10);
    if (end == argv[1] || *end != '\0' || errno == ERANGE || n < 0) {
        fprintf(stderr, "N must be a non-negative integer\n");
        return EXIT_FAILURE;
    }

    /* Each Fibonacci step increases its decimal length by at most one.
       Since log10(phi) is about 0.209, n / 5 plus a small constant is a
       safe capacity and avoids allocating n digits for every work array. */
    size_t capacity = (size_t)n / 5 + 8;
    unsigned char *storage = calloc(3, capacity);
    if (storage == NULL) {
        fprintf(stderr, "out of memory\n");
        return EXIT_FAILURE;
    }

    unsigned char *a = storage;
    unsigned char *b = storage + capacity;
    unsigned char *next = storage + 2 * capacity;
    size_t a_length = 1;
    size_t b_length = 1;
    a[0] = 0;
    b[0] = 1;

    for (long long i = 0; i < n; ++i) {
        size_t length = a_length > b_length ? a_length : b_length;
        unsigned char carry = 0;

        for (size_t j = 0; j < length; ++j) {
            unsigned int left = j < a_length ? a[j] : 0;
            unsigned int right = j < b_length ? b[j] : 0;
            unsigned int sum = left + right + carry;
            next[j] = (unsigned char)(sum % 10);
            carry = (unsigned char)(sum / 10);
        }
        if (carry != 0) {
            next[length++] = carry;
        }

        unsigned char *temporary_pointer = a;
        a = next;
        next = b;
        b = temporary_pointer;
        size_t temporary_length = a_length;
        a_length = b_length;
        b_length = temporary_length;
    }

    for (size_t i = a_length; i > 0; --i) {
        putchar('0' + a[i - 1]);
    }
    putchar('\n');

    free(storage);
    return EXIT_SUCCESS;
}
